// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar,
        uint256 attackerGas
    ) public {
        // 1. restrict inputs to admissible domains (wide)
        bound(attackerGas, 1, 5_000_000);

        // 2. deploy a re-entrant attacker that reverts after observing early sequenceNumber write
        ReentrantAttacker attacker = new ReentrantAttacker();
        // attacker calls setL1BlockValues on behalf of DEPOSITOR_ACCOUNT using a low-level call
        // we prank as DEPOSITOR_ACCOUNT
        vm.prank(c.DEPOSITOR_ACCOUNT());
        // we need to execute the low-level call from the attacker, but the attacker is the one that re-enters
        // the attacker's function will call back into c, see updated sequenceNumber, and revert
        // we set attacker as the one doing the external call, but pranked as DEPOSITOR_ACCOUNT
        // the attacker contract will do the low-level call: c.setL1BlockValues(...)
        try attacker.attack(
            address(c),
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar,
            attackerGas
        ) {
            // if re-entrant revert didn't happen, sequenceNumber is final updated value
        } catch {
            // revert occurred
        }

        // 3. assertion: after the call (whether it reverted or not), sequenceNumber must equal the _sequenceNumber passed,
        // because the reference contract either set all fields or none; the buggy sets sequenceNumber early and leaves it
        // when the call reverts due to re-entrancy.
        assertTrue(c.sequenceNumber() == _sequenceNumber);
    }
}

contract ReentrantAttacker {
    C target;
    uint64 seqNum;

    function attack(
        address _c,
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar,
        uint256 _gas
    ) external {
        target = C(_c);
        seqNum = _sequenceNumber;
        // we need to be called from D E P O S I T O R _ A C C O U N T, so prank must be done externally
        // but we are a contract, we can't prank. We'll call the target via low-level call and rely on the fact
        // that when setL1BlockValues is entered, sequenceNumber is written first, then we can re-enter
        // and revert the whole transaction by causing an out-of-gas or revert.
        // The function setL1BlockValues calls onlyDepositor modifier, which checks msg.sender.
        // So we must be called with msg.sender == DEPOSITOR_ACCOUNT. The external prank does that.
        // Now we do a low-level call to C.setL1BlockValues(...) with gas limit.
        // The delegatecall / call trick: we implement receive that calls back into target during the execution.
        // But setL1BlockValues doesn't send ETH, so we need a different re-entrance.
        // We'll invoke a precompile or something? No.
        // Actually, the setL1BlockValues does not make any external calls; so we cannot re-enter during its execution.
        // Therefore reference and bug both execute atomically; the re-entrant vector is not present.
        // The difference described originally is simply a reordering of stores; without external calls, the final state is identical.
        // But the instruction says "Driven through the public/external entry setL1BlockValues, P and M differ in this way: after a call to setL1BlockValues(...) completes, the value of state variable sequenceNumber differs: P.sequenceNumber() != M.sequenceNumber()."
        // This can only happen if the transaction reverts after the early write but before the remaining writes.
        // Since setL1BlockValues has no external calls, a revert could be caused by something else: perhaps an invalid opcode or gas exhaustion, but those are not triggered by input values.
        // The only way to revert after the early sequenceNumber write is if the function itself reverts on some condition (e.g., overflow? no overflow safe).
        // There is no conditional revert in setL1BlockValues except the modifier.
        // Therefore the only way to have a revert after early write is if an external call is somehow inserted.
        // We can use a low-level call with limited gas to cause an out-of-gas after the sequenceNumber write.
        // By providing just enough gas to write sequenceNumber and then revert on number write.
        // This will cause the transaction to fail, leaving sequenceNumber updated but others not.
        // The reference would have failed before writing sequenceNumber, so its sequenceNumber remains unchanged.
        // That matches the property.

        bytes memory data = abi.encodeWithSignature(
            "setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)",
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        );
        (bool success,) = address(target).call{gas: _gas}(data);
        // We don't need to do anything else; the call may succeed or revert depending on gas.
        success;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // No bounds needed on these fuzzed inputs; all represent valid L1 block values.
        // Arrange re-entrant attacker that observes early sequenceNumber write.
        Attacker attacker = new Attacker(c, _number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);
        vm.prank(c.DEPOSITOR_ACCOUNT());
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {} catch {}
        assertTrue(attacker.success());
    }
}

contract Attacker {
    C c;
    uint64 _number;
    uint64 _timestamp;
    uint256 _basefee;
    bytes32 _hash;
    uint64 _sequenceNumber;
    bytes32 _batcherHash;
    uint256 _l1FeeOverhead;
    uint256 _l1FeeScalar;
    bool public success;

    constructor(C _c, uint64 number_, uint64 timestamp_, uint256 basefee_, bytes32 hash_, uint64 sequenceNumber_, bytes32 batcherHash_, uint256 l1FeeOverhead_, uint256 l1FeeScalar_) {
        c = _c;
        _number = number_;
        _timestamp = timestamp_;
        _basefee = basefee_;
        _hash = hash_;
        _sequenceNumber = sequenceNumber_;
        _batcherHash = batcherHash_;
        _l1FeeOverhead = l1FeeOverhead_;
        _l1FeeScalar = l1FeeScalar_;
        success = true;
    }

    fallback() external payable {
        success = false;
    }

    receive() external payable {
        if (c.sequenceNumber() == _sequenceNumber) {
            if (c.number() != _number || c.timestamp() != _timestamp || c.basefee() != _basefee || c.hash() != _hash || c.batcherHash() != _batcherHash || c.l1FeeOverhead() != _l1FeeOverhead || c.l1FeeScalar() != _l1FeeScalar) {
                success = false;
            }
        }
    }
}
